struct Rollback<'a> { tx: &'a Tx, committed: bool }
impl Drop for Rollback<'_> {
    fn drop(&mut self) { if !self.committed { self.tx.rollback(); } }
}

let mut guard = Rollback { tx: &tx, committed: false };
apply(&tx)?;                    // error or panic -> rollback in drop
tx.commit();
guard.committed = true;         // disarmed before the scope ends

