use scopeguard::{guard, defer};
{
    let file = File::create("newfile.txt")?;
    let mut file = guard(file, |f| { let _ = f.sync_all(); });  // flushed at exit
    file.write_all(b"hello")?;
}                                  // sync_all runs here, on return or panic
defer! { println!("scope exited"); }
